ALTER TABLE `gb_sip_security_ban` ADD COLUMN `trigger_method` VARCHAR(16) NOT NULL DEFAULT '' AFTER `last_error`, ADD COLUMN `trigger_count` INT NOT NULL DEFAULT 0 AFTER `trigger_method`, ADD COLUMN `trigger_threshold` INT NOT NULL DEFAULT 0 AFTER `trigger_count`, ADD COLUMN `window_seconds` INT NOT NULL DEFAULT 0 AFTER `trigger_threshold`, ADD COLUMN `policy_mode` VARCHAR(16) NOT NULL DEFAULT '' AFTER `window_seconds`, ADD COLUMN `firewall_applied_at` DATETIME NULL AFTER `policy_mode`, ADD COLUMN `blocked_count_after_ban` BIGINT NOT NULL DEFAULT 0 AFTER `firewall_applied_at`, ADD COLUMN `last_blocked_at` DATETIME NULL AFTER `blocked_count_after_ban`;
